// Valider le lot d'un étage – contrôle du corps de la requête. Chaque rapport doit rester rattaché à son BROUILLON
// (contrôlé ensuite par la brique « enregistrer ») : rien d'autre que ces textes n'est enregistré.
const b = $input.first().json?.body ?? {};
const etage = Number(b.etage);
if (!Number.isInteger(etage) || etage < 0 || etage > 20) throw new Error('étage invalide');
if (!Array.isArray(b.rapports) || b.rapports.length === 0 || b.rapports.length > 60) throw new Error('rapports : 1 à 60 attendus');
// Le nom du soignant qui valide vient de sa SESSION (jeton), jamais du corps de la requête : on ne peut pas valider « au nom de » quelqu'un d'autre.
const s = $('Session').first().json.soignant;
return b.rapports.map((r) => ({ json: { brouillon_id: r?.brouillon_id, texte: r?.texte, valide_par: s.nom, soignant_id: s.identifiant, etage } }));

// Valider le lot d'un étage – rassemble les validations réussies ; les refus (déjà validé, introuvable, texte vide) sont listés.
const etage = $('Corps du lot').first().json.etage;
const sorties = $input.all().map((i) => i.json);
const valides = sorties.filter((s) => s.ok === true && s.action === 'generer_sbar');
const refuses = sorties
  .filter((s) => !(s.ok === true && s.action === 'generer_sbar'))
  .map((s) => ({ brouillon_id: s.brouillon_id ?? null, erreur: String(s.erreur ?? s.error?.message ?? s.error ?? 'Validation refusée').slice(0, 200) }));
return [{ json: { portee: 'etage', etage, validation_ids: valides.map((s) => s.validation_id), nb_valides: valides.length, refuses } }];

// Valider le lot d'un étage – réponse à l'interface.
const l = $('Rassembler le lot').first().json;
const a = $input.first().json ?? {};
return [
  {
    json: {
      ok: l.nb_valides > 0,
      nb_valides: l.nb_valides,
      refuses: l.refuses,
      apres_validation: l.nb_valides === 0 ? null : a.error ? { erreur: String(a.error.message ?? a.error).slice(0, 200) } : { rag: a.rag, transmission: a.transmission },
    },
  },
];

// Valider le lot d'un étage – réponse à l'interface.
const l = $('Rassembler le lot').first().json;
const a = $input.first().json ?? {};
return [
  {
    json: {
      ok: l.nb_valides > 0,
      nb_valides: l.nb_valides,
      refuses: l.refuses,
      apres_validation: l.nb_valides === 0 ? null : a.error ? { erreur: String(a.error.message ?? a.error).slice(0, 200) } : { rag: a.rag, transmission: a.transmission },
    },
  },
];

// Contrôle de session – le jeton « Bearer » de l'en-tête Authorization (43 caractères URL-safe) est haché (SHA-256) : seul le haché est en base.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Contrôle de session – résultat : un soignant identifié (session ouverte, non expirée, compte actif) ou rien.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
